import{_ as t,o as s,c as a,a4 as r}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse('{"title":"ADR-0036 — Refuser les cookies ne ferme pas le service : repli Altcha quand le captcha tiers est soumis au consentement","description":"Extrait de docs/adr/0036-captcha-sans-consentement-repli-altcha.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0036 — Refuser les cookies ne ferme pas le service : repli Altcha quand le captcha tiers est soumis au consentement","description":"Extrait de docs/adr/0036-captcha-sans-consentement-repli-altcha.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0036-captcha-sans-consentement-repli-altcha.md","filePath":"developpeurs/adr/0036-captcha-sans-consentement-repli-altcha.md"}'),i={name:"developpeurs/adr/0036-captcha-sans-consentement-repli-altcha.md"};function n(c,e,l,o,u,d){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0036--refuser-les-cookies-ne-ferme-pas-le-service--repli-altcha-quand-le-captcha-tiers-est-soumis-au-consentement" tabindex="-1">ADR-0036 — Refuser les cookies ne ferme pas le service : repli Altcha quand le captcha tiers est soumis au consentement <a class="header-anchor" href="#adr-0036--refuser-les-cookies-ne-ferme-pas-le-service--repli-altcha-quand-le-captcha-tiers-est-soumis-au-consentement" aria-label="Permalink to &quot;ADR-0036 — Refuser les cookies ne ferme pas le service : repli Altcha quand le captcha tiers est soumis au consentement {#adr-0036--refuser-les-cookies-ne-ferme-pas-le-service--repli-altcha-quand-le-captcha-tiers-est-soumis-au-consentement}&quot;">​</a></h1><p><strong>Date :</strong> 19 septembre 2026 <strong>Statut :</strong> Accepté avec garde-fou <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> revue documentaire du 18/09/2026 (contradiction relevée dans <code>docs/adr/actions-ouvertes.md</code>) ; RGPD art. 4(11) et 7(4) ; directive ePrivacy art. 5(3) ; lignes directrices et recommandation « cookies et autres traceurs » de la CNIL ; résout l&#39;action liée de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0033-captchas-tiers-declares-d-office">ADR-0033</a>, s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0015-captcha-non-configure-refus-de-soumission">ADR-0015</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Deux décisions, justes chacune, se contredisaient :</p><ul><li><strong>l&#39;ADR-0015</strong> exige un captcha sur toute écriture publique, et depuis le 18/09 aussi sur l&#39;inscription et les abonnements ;</li><li><strong>l&#39;ADR-0033</strong> soumet par défaut au consentement les captchas tiers (Cloudflare Turnstile, hCaptcha), parce qu&#39;ils chargent un script de leur éditeur chez l&#39;usager.</li></ul><p>Un visiteur qui refusait les cookies ne pouvait donc plus charger le captcha, et <strong>ne pouvait plus faire une démarche en ligne</strong>. Le refus lui coûtait l&#39;accès au service.</p><p>Or un consentement n&#39;est valable que s&#39;il est libre, c&#39;est-à-dire si le refuser n&#39;entraîne pas de préjudice (RGPD, art. 4(11) et 7(4)). La CNIL admet de subordonner un service à l&#39;acceptation seulement au cas par cas, et à condition qu&#39;une alternative réelle existe. Pour un <strong>service public</strong>, qui n&#39;a pas de concurrent vers lequel se tourner, cette alternative doit exister sur place. L&#39;ADR-0033 le savait, et laissait l&#39;action ouverte.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Quand le captcha actif est un service tiers, un second vérificateur, Altcha, est proposé d&#39;office au visiteur qui n&#39;a pas consenti à ce service.</strong></p><ol><li><p><strong>Altcha ne relève pas du consentement.</strong> C&#39;est une preuve de travail émise et vérifiée par ce serveur (ADR-0027) : aucun cookie, aucun tiers contacté, aucune adresse IP transmise. Rien n&#39;est lu ni écrit dans le terminal de l&#39;usager au sens de l&#39;article 5(3) de la directive ePrivacy, au-delà du calcul que la page lui demande.</p></li><li><p><strong>Le repli est actif par défaut</strong> (<code>CAPTCHA_CONSENT_FALLBACK=altcha</code>). On peut le couper (<code>off</code>), et l&#39;exploitant qui le fait endosse la contradiction ; la notice le dit.</p></li><li><p><strong>Aucun secret de plus à configurer.</strong> La clé qui signe les défis du repli est dérivée de <code>CAPTCHA_SECRET_KEY</code>. La protection contre le rejeu est la même que pour Altcha en fournisseur principal.</p></li><li><p><strong>Le site public sait, avant la saisie, lequel afficher.</strong> L&#39;état du captcha servi par l&#39;API annonce le repli et la clé du service de cookies du captcha tiers. Le site affiche le captcha tiers si le visiteur y a consenti, ou si le DPO l&#39;a déclaré strictement nécessaire (ADR-0033) ; il affiche Altcha dans tous les autres cas.</p></li><li><p><strong>Le serveur accepte l&#39;un ou l&#39;autre.</strong> Un jeton Altcha se reconnaît à sa forme, qu&#39;un jeton Turnstile ou hCaptcha n&#39;a jamais : aucune route publique n&#39;a changé de contrat.</p></li></ol><p><strong>Le garde-fou</strong>, qui fait de cette ADR un « Accepté avec garde-fou » : <strong>le serveur ne peut pas savoir si le visiteur a refusé</strong>, et un robot peut donc choisir le repli. Le plancher de protection devient celui d&#39;Altcha, complété par la limitation de débit (ADR-0031). C&#39;est le prix d&#39;un service public accessible sans consentement, et c&#39;est exactement le niveau d&#39;une installation qui choisit Altcha d&#39;emblée. Un DPO qui a déclaré le captcha tiers strictement nécessaire sur <strong>tous</strong> ses sites peut couper le repli et retrouver la protection complète.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Laisser le refus bloquer la démarche</strong></td><td>Consentement non libre (RGPD art. 7(4)) ; pour un service public, aucune alternative ailleurs. C&#39;était la situation à corriger.</td></tr><tr><td><strong>Déclarer d&#39;office les captchas tiers strictement nécessaires</strong></td><td>Trancherait à la place du DPO ce que l&#39;ADR-0033 lui confie, pour des services qui transmettent des données à un tiers.</td></tr><tr><td><strong>Un autre canal de dépôt</strong> (courrier, accueil, téléphone)</td><td>Il existe déjà hors du CMS, et il ne rend pas le formulaire accessible : renvoyer au guichet celui qui refuse un cookie n&#39;est pas une alternative réelle en ligne.</td></tr><tr><td><strong>Supprimer le captcha pour qui refuse</strong></td><td>Ouvrirait toutes les écritures publiques aux robots, au mépris de l&#39;ADR-0015.</td></tr><tr><td><strong>Transmettre au serveur le choix de consentement du visiteur</strong></td><td>Le serveur ne pourrait pas le vérifier : un robot le falsifierait. Cela n&#39;ajoute aucune protection et crée une donnée de plus.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Refuser les cookies ne coûte plus l&#39;accès aux démarches en ligne, à l&#39;inscription ni aux abonnements.</li><li>Aucun contrat de route publique ne change, et aucun secret n&#39;est à configurer.</li><li>Altcha étant invisible pour l&#39;usager, le repli est aussi plus accessible qu&#39;un captcha à défi visuel (RGAA).</li></ul><p><strong>Négatives</strong></p><ul><li>La protection effective d&#39;une instance qui utilise un captcha tiers descend au niveau d&#39;Altcha pour qui choisit le repli, robots compris.</li><li>Le site public doit gérer deux widgets et choisir selon le consentement du visiteur. Ce dépôt ne livre pas de site public : la notice lui dit quoi faire.</li><li>Une preuve de travail coûte du calcul sur un appareil ancien (déjà relevé par l&#39;ADR-0015, action RGAA ouverte).</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[ ] Réévaluer le seuil de difficulté d&#39;Altcha (<code>ALTCHA_MAX_NUMBER</code>) si l&#39;on constate que le repli devient le chemin des robots. Aujourd&#39;hui, rien ne permet de le mesurer : aucun journal ne distingue les jetons du repli de ceux du captcha principal.</li></ul>',20)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
